'kirwan|les-charmes-de-kirwan|2018':{blend:{CS:44,ME:56},src:'2018-CHARMES-DE-KIRWAN-FACT-SHEET-GB.pdf'},
'kirwan|les-charmes-de-kirwan|2019':{blend:{CS:58,ME:32,CF:10},press:{'Decanter':'91','James Suckling':'90'},src:'2019-CHARMES-DE-KIRWAN-FACT-SHEET-GB.pdf'},
'kirwan|les-charmes-de-kirwan|2020':{blend:{CS:50,ME:45,PV:5},press:{'James Suckling':'90'},src:'2020-CHARMES-DE-KIRWAN-FACT-SHEET-GB.pdf'},
