'la-conseillante|duo-de-conseillante|2012':{blend:{ME:90,CF:10},alc:13,months:'18',src:'Fiche-technique-Duo-de-Conseillante-2012.pdf',oak:65,yld:39},
'la-conseillante|duo-de-conseillante|2013':{blend:{ME:90,CF:10},alc:13,months:'18',src:'Fiche-technique-Duo-de-Conseillante-2013.pdf',note:'Rain and heat before and during the harvest did not facilitate the harvest and we had to work with optical sorting to have the best possible selection. However, the wines are good, fermentations took place without problem, the quality was homogeneous. Smooth, the wine develops raspberry notes.',oak:65,yld:30},
'la-conseillante|duo-de-conseillante|2014':{blend:{ME:90,CF:10},alc:13,months:'18',src:'Fiche-technique-Duo-de-Conseillante-2014.pdf',oak:65,yld:38},
'la-conseillante|duo-de-conseillante|2015':{blend:{ME:88,CF:12},alc:14.5,months:'18',src:'Fiche-technique-Duo-de-Conseillante-2015.pdf',oak:50,yld:39.5},
'la-conseillante|duo-de-conseillante|2016':{alc:14,months:'18',src:'Fiche-technique-Duo-de-Conseillante-2016.pdf',blend:{CF:20,ME:80},oak:50,ph:3.65,yld:39},
