'la-conseillante|duo-de-conseillante|2019':{blend:{ME:72,CF:28},alc:14.5,months:'16',src:'Fiche-technique-Duo-de-Conseillante-2019.pdf',tau:'?',oak:50,ph:3.63,pick:{ALL:'09-17|09-20'},ta:3.15,tau:'?',wy:[2022,2030],yld:34},
