'la-conseillante|duo-de-conseillante|2021':{blend:{ME:90,CF:10},alc:13,months:'14',src:'Fiche-technique-Duo-de-Conseillante-2021.pdf',tau:'?',oak:50,ph:3.59,ta:3.42,tau:'?',wy:[2024,2034],yld:39},
