'malartic-lagraviere|le-comte-de-malartic|2019':{blend:{CS:12.3,ME:82.6,PV:5.1},yld:46,months:'16',oak:25,src:'le-comte-de-malartic-red-2019.pdf',pick:{ALL:'10-01|10-11'},wy:[2023,2038]},
